<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Order extends Model{protected $fillable=['user_id','order_number','status','payment_method','payment_status','subtotal','shipping_fee','total','shipping_name','shipping_phone','shipping_address','notes'];protected $casts=['subtotal'=>'decimal:2','shipping_fee'=>'decimal:2','total'=>'decimal:2'];public function user(){return $this->belongsTo(User::class);}public function items(){return $this->hasMany(OrderItem::class);}
public function vendorOrders(){return $this->hasMany(VendorOrder::class);}}
